package org.slavicmyths.burningislands;
import java.util.*;import java.lang.ref.WeakReference;
import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.nbt.*;
import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.chunk.*;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.attachment.AttachmentType;import net.neoforged.neoforge.registries.*;
/** Provenance and lease ORIGINAL+PLACED+OWNER+EXPIRY serialize WITH the block in its chunk.
 * No second-file save-order assumption; loaded leases restore on chunk load, scheduled ticks expire live leases.
 * External writes revoke provenance, including identical-looking player replacements. */
@EventBusSubscriber(modid="slavicmyths")
public final class TemporaryTerrain {
 public static final DeferredRegister<AttachmentType<?>> TYPES=DeferredRegister.create(NeoForgeRegistries.Keys.ATTACHMENT_TYPES,"slavicmyths");
 public static final DeferredHolder<AttachmentType<?>,AttachmentType<CompoundTag>> DATA=TYPES.register("islands_terrain_provenance",()->AttachmentType.builder(()->new CompoundTag()).serialize(CompoundTag.CODEC).build());
 private static final ThreadLocal<Boolean> WRITING=ThreadLocal.withInitial(()->false);
 private static final Map<ServerLevel,Map<Long,WeakReference<LevelChunk>>> ACTIVE=new WeakHashMap<>();
 public static void init(net.neoforged.bus.api.IEventBus bus){TYPES.register(bus);}
 private static CompoundTag child(CompoundTag data,String name){if(!data.contains(name,10))data.put(name,new CompoundTag());return data.getCompound(name);}
 private static String key(BlockPos p){return Long.toString(p.asLong());}
 public static void natural(ChunkAccess chunk,BlockPos p,BlockState state){var data=chunk.getData(DATA);data.putInt("Version",1);var ground=child(data,"Ground");if(ground.size()<256||ground.contains(key(p))){ground.put(key(p),NbtUtils.writeBlockState(state));chunk.setUnsaved(true);}}
 public static void externalWrite(LevelChunk c,BlockPos p){if(WRITING.get()||!c.hasData(DATA))return;var data=c.getData(DATA);if(data.getInt("Version")!=1)return;var ground=data.getCompound("Ground");var leases=data.getCompound("Leases");boolean present=ground.contains(key(p))||leases.contains(key(p));ground.remove(key(p));leases.remove(key(p));if(present)c.setUnsaved(true);}
 private static CompoundTag lease(ServerLevel s,BlockPos p){if(!s.hasChunkAt(p))return new CompoundTag();var c=s.getChunkAt(p);if(!c.hasData(DATA))return new CompoundTag();return c.getData(DATA).getCompound("Leases").getCompound(key(p));}
 public static boolean leased(ServerLevel s,BlockPos p){return !lease(s,p).isEmpty();}
 private static boolean ground(ServerLevel s,BlockPos p){if(!s.hasChunkAt(p)||s.getBlockEntity(p)!=null)return false;var c=s.getChunkAt(p);if(!c.hasData(DATA)||c.getData(DATA).getInt("Version")!=1)return false;var tag=c.getData(DATA).getCompound("Ground").getCompound(key(p));return !tag.isEmpty()&&NbtUtils.readBlockState(s.holderLookup(Registries.BLOCK),tag).equals(s.getBlockState(p));}
 public static boolean magma(ServerPlayer owner){var p=owner.blockPosition().below();var s=owner.serverLevel();if(!s.dimension().equals(Level.NETHER)||!ground(s,p)||leased(s,p))return false;var old=s.getBlockState(p);if(!old.is(Blocks.BLACKSTONE)&&!old.is(Blocks.BASALT)&&!old.is(Blocks.OBSIDIAN))return false;return place(owner,p,Blocks.MAGMA_BLOCK.defaultBlockState(),120);}
 /** Engineering prototype: at most4 real, non-spreading fire cells for60t, only proven natural island ground. */
 public static int fire(ServerPlayer owner,LivingEntity target){var s=owner.serverLevel();if(!s.getGameRules().getBoolean(GameRules.RULE_DOFIRETICK)||!s.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING))return 0;int count=0;BlockPos center=target.blockPosition();for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){var p=center.offset(d[0],0,d[1]);if(!s.hasChunkAt(p)||!s.isEmptyBlock(p)||!ground(s,p.below())||leased(s,p))continue;boolean safe=true;
  for(BlockPos q:BlockPos.betweenClosed(p.offset(-2,-1,-2),p.offset(2,3,2))){if(!s.hasChunkAt(q)||s.getBlockEntity(q)!=null){safe=false;break;}var b=s.getBlockState(q);if(!b.isAir()&&!b.is(Blocks.BLACKSTONE)&&!b.is(Blocks.BASALT)&&!b.is(Blocks.OBSIDIAN)&&!b.is(Blocks.MAGMA_BLOCK)&&!b.is(Blocks.LAVA)&&!b.is(Blocks.FIRE)){safe=false;break;}}
  if(safe&&Blocks.FIRE.defaultBlockState().canSurvive(s,p)&&place(owner,p,Blocks.FIRE.defaultBlockState(),60))count++;
 }return count;}
 private static boolean place(ServerPlayer owner,BlockPos p,BlockState placed,int ttl){var s=owner.serverLevel();if(WRITING.get()||!s.hasChunkAt(p)||!s.getWorldBorder().isWithinBounds(p)||!s.mayInteract(owner,p)||!owner.mayUseItemAt(p,Direction.UP,owner.getMainHandItem())||s.getBlockEntity(p)!=null||!s.getFluidState(p).isEmpty())return false;
  var c=s.getChunkAt(p);var data=c.getData(DATA);if(data.getInt("Version")!=1)return false;var leases=child(data,"Leases");var active=ACTIVE.computeIfAbsent(s,w->new HashMap<>());if(leases.size()>=32||leases.contains(key(p))||active.size()>=512&&!active.containsKey(c.getPos().toLong()))return false;BlockState original=s.getBlockState(p);var snapshot=net.neoforged.neoforge.common.util.BlockSnapshot.create(s.dimension(),s,p);boolean committed=false;leases.put(key(p),TerrainLeaseRules.create(original,placed,owner.getUUID(),s.getServer().overworld().getGameTime()+ttl));c.setUnsaved(true);WRITING.set(true);
  try{if(!s.setBlock(p,placed,3))return false;var event=new net.neoforged.neoforge.event.level.BlockEvent.EntityPlaceEvent(snapshot,s.getBlockState(p.below()),owner);if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event).isCanceled()||!s.getBlockState(p).equals(placed))return false;
   c.setUnsaved(true);active.put(c.getPos().toLong(),new WeakReference<>(c));s.scheduleTick(p,placed.getBlock(),ttl);committed=true;return true;
  }finally{if(!committed){if(s.getBlockState(p).equals(placed))s.setBlock(p,original,3);leases.remove(key(p));c.setUnsaved(true);}WRITING.remove();}
 }
 public static boolean scheduled(ServerLevel s,BlockPos p){var entry=lease(s,p);if(entry.isEmpty())return false;long remaining=entry.getLong("Until")-s.getServer().overworld().getGameTime();if(remaining<=0)restore(s,s.getChunkAt(p),p);else s.scheduleTick(p,s.getBlockState(p).getBlock(),(int)Math.min(remaining,120));return true;}
 private static void restore(ServerLevel s,LevelChunk c,BlockPos p){var leases=c.getData(DATA).getCompound("Leases");var entry=leases.getCompound(key(p));if(entry.isEmpty())return;var lookup=s.holderLookup(Registries.BLOCK);var expected=NbtUtils.readBlockState(lookup,entry.getCompound("Placed"));var original=NbtUtils.readBlockState(lookup,entry.getCompound("Original"));WRITING.set(true);try{if(TerrainLeaseRules.mayRestore(entry,s.getBlockState(p))&&s.getBlockEntity(p)==null)s.setBlock(p,original,3);leases.remove(key(p));c.setUnsaved(true);}finally{WRITING.remove();}if(leases.isEmpty()){var map=ACTIVE.get(s);if(map!=null)map.remove(c.getPos().toLong());}}
 private static void restoreChunk(ServerLevel s,LevelChunk c,UUID owner){if(!c.hasData(DATA)||c.getData(DATA).getInt("Version")!=1)return;for(String raw:List.copyOf(c.getData(DATA).getCompound("Leases").getAllKeys())){var e=c.getData(DATA).getCompound("Leases").getCompound(raw);if(owner==null||e.hasUUID("Owner")&&owner.equals(e.getUUID("Owner")))try{restore(s,c,BlockPos.of(Long.parseLong(raw)));}catch(NumberFormatException ignored){/* unknown/malformed provenance is never applied */}}}
 @SubscribeEvent public static void load(net.neoforged.neoforge.event.level.ChunkEvent.Load e){if(e.getChunk() instanceof LevelChunk c&&e.getLevel() instanceof ServerLevel s)s.getServer().execute(()->{if(s.hasChunk(c.getPos().x,c.getPos().z))restoreChunk(s,c,null);});}
 @SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.ChunkEvent.Unload e){if(e.getChunk() instanceof LevelChunk c&&e.getLevel() instanceof ServerLevel s){restoreChunk(s,c,null);var map=ACTIVE.get(s);if(map!=null)map.remove(c.getPos().toLong());}}
 private static void owner(ServerPlayer p){for(var s:p.getServer().getAllLevels()){var map=ACTIVE.get(s);if(map!=null)for(var ref:List.copyOf(map.values())){var c=ref.get();if(c!=null&&s.hasChunk(c.getPos().x,c.getPos().z))restoreChunk(s,c,p.getUUID());}}}
 @SubscribeEvent public static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent e){if(e.getEntity() instanceof ServerPlayer p)owner(p);}
 @SubscribeEvent public static void dimension(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerChangedDimensionEvent e){if(e.getEntity() instanceof ServerPlayer p)owner(p);}
 @SubscribeEvent public static void death(net.neoforged.neoforge.event.entity.living.LivingDeathEvent e){if(e.getEntity() instanceof ServerPlayer p)owner(p);}
 @SubscribeEvent public static void broken(net.neoforged.neoforge.event.level.BlockEvent.BreakEvent e){if(e.getLevel() instanceof ServerLevel s&&leased(s,e.getPos()))e.setCanceled(true);}
 @SubscribeEvent public static void piston(net.neoforged.neoforge.event.level.PistonEvent.Pre e){if(!(e.getLevel() instanceof ServerLevel s))return;var resolver=e.getStructureHelper();if(resolver.resolve()&&(resolver.getToPush().stream().anyMatch(p->leased(s,p))||resolver.getToDestroy().stream().anyMatch(p->leased(s,p))))e.setCanceled(true);}
 @SubscribeEvent public static void explosion(net.neoforged.neoforge.event.level.ExplosionEvent.Detonate e){if(e.getLevel() instanceof ServerLevel s)e.getAffectedBlocks().removeIf(p->leased(s,p));}
 public static boolean protectedFromFire(ServerLevel s,BlockPos p,Entity entity){var e=lease(s,p);if(e.isEmpty())return false;var owner=e.hasUUID("Owner")?s.getServer().getPlayerList().getPlayer(e.getUUID("Owner")):null;return entity instanceof net.minecraft.world.entity.player.Player||entity instanceof TamableAnimal t&&t.isTame()||entity.getType().is(org.slavicmyths.combat.CombatTargeting.PROTECTED)||owner!=null&&entity.isAlliedTo(owner);}
 @SubscribeEvent public static void stopping(net.neoforged.neoforge.event.server.ServerStoppingEvent e){for(var s:e.getServer().getAllLevels()){var map=ACTIVE.get(s);if(map!=null)for(var ref:List.copyOf(map.values())){var c=ref.get();if(c!=null&&s.hasChunk(c.getPos().x,c.getPos().z))restoreChunk(s,c,null);}}}
 @SubscribeEvent public static void floorHarm(net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent e){if(!(e.getEntity().level() instanceof ServerLevel s)||!e.getSource().is(net.minecraft.tags.DamageTypeTags.IS_FIRE))return;var living=e.getEntity();var pos=living.blockPosition();var a=lease(s,pos);if(a.isEmpty())a=lease(s,pos.below());if(a.isEmpty())return;var owner=a.hasUUID("Owner")?s.getServer().getPlayerList().getPlayer(a.getUUID("Owner")):null;if(living instanceof net.minecraft.world.entity.player.Player||living instanceof TamableAnimal t&&t.isTame()||living.getType().is(org.slavicmyths.combat.CombatTargeting.PROTECTED)||owner!=null&&living.isAlliedTo(owner))e.setCanceled(true);}
 private TemporaryTerrain(){}
}
